import React from 'react'
import { ArrowLeft, AlertTriangle, CheckCircle2, Tag, TrendingUp, TrendingDown } from 'lucide-react'
import styles from './StockDetailScreen.module.css'

export default function StockDetailScreen({ selectedStock, setCurrentScreen, previousScreen }) {

  if (!selectedStock) return null

  const s = selectedStock

  // ---- 投資判断ロジック（UI だけのため / 売買助言ではない）----
  const verdict =
    s.overall >= 80 ? { label: '強気', color: '#16a34a' } :
    s.overall >= 60 ? { label: 'やや強気', color: '#22c55e' } :
    s.overall >= 40 ? { label: '中立', color: '#6b7280' } :
                      { label: '弱気', color: '#dc2626' }

  const risks = []
  if (s.volatility > 25) risks.push('ボラティリティが高い')
  if (s.marginRatio > 3) risks.push('信用買いが過熱')
  if (s.pbr > 3) risks.push('PBRが割高水準')
  if (s.roe < 8) risks.push('ROEが低収益水準')

  return (
    <div className={styles.container}>

      {/* 戻る */}
      <div className={styles.header}>
        <button onClick={() => setCurrentScreen(previousScreen || 'list')} className={styles.backButton}>
          <ArrowLeft size={18} />
          戻る
        </button>
      </div>

      {/* ------------- ① 投資判断サマリー ------------- */}
      <div className={styles.section}>
        <h3 className={styles.sectionTitle}>投資判断</h3>

        <div
          className={styles.summaryCard}
          style={{ borderLeft: `6px solid ${verdict.color}` }}
        >
          <div className={styles.summaryRow}>
            <span className={styles.summaryLabel}>結論</span>
            <span className={styles.summaryValue} style={{ color: verdict.color }}>
              {verdict.label}
            </span>
          </div>

          <div className={styles.summaryRow}>
            <span className={styles.summaryLabel}>総合スコア</span>
            <span className={styles.summaryValue}>{s.overall} / 100</span>
          </div>

          <div className={styles.summaryRow}>
            <span className={styles.summaryLabel}>現在価格</span>
            <span className={styles.summaryValue}>¥{s.price?.toLocaleString()}</span>
          </div>
        </div>
      </div>

      {/* ------------- ② 投資テーマタグ ------------- */}
      <div className={styles.section}>
        <h3 className={styles.sectionTitle}>
          <Tag size={18}/> 投資テーマ
        </h3>
        <div className={styles.tagGroup}>
          {s.dividendYield > 4 && <span className={styles.tag}>高配当</span>}
          {s.pbr < 1 && <span className={styles.tag}>低PBR改善候補</span>}
          {s.roe > 15 && <span className={styles.tag}>高収益</span>}
          {s.beta > 1.2 && <span className={styles.tag}>ハイボラ</span>}
          {s.marketTheme?.map((t,i)=> <span key={i} className={styles.tag}>{t}</span>)}
        </div>
      </div>

      {/* ------------- ③ 重要指標の要約 ------------- */}
      <div className={styles.section}>
        <h3 className={styles.sectionTitle}>主要指標</h3>

        <div className={styles.metricsQuick}>
          <div><label>PER</label><span>{s.per}倍</span></div>
          <div><label>PBR</label><span>{s.pbr}倍</span></div>
          <div><label>ROE</label><span>{s.roe}%</span></div>
          <div><label>配当利回り</label><span>{s.dividendYield}%</span></div>
          <div><label>信用倍率</label><span>{s.marginRatio}倍</span></div>
          <div><label>出来高比率</label><span>{s.volumeRatio}%</span></div>
        </div>
      </div>

      {/* ------------- ④ トレンドシグナル ------------- */}
      <div className={styles.section}>
        <h3 className={styles.sectionTitle}>トレンドシグナル</h3>

        <div className={styles.signalList}>
          {s.change > 0
            ? <div className={styles.signalPositive}><TrendingUp/> 上昇トレンド気味</div>
            : <div className={styles.signalNegative}><TrendingDown/> 調整トレンド気味</div>}

          {s.volumeRatio > 150 && <div className={styles.signalPositive}><CheckCircle2/> 出来高増加</div>}
          {s.marginRatio > 3 && <div className={styles.signalNegative}><AlertTriangle/> 信用買い過熱</div>}
        </div>
      </div>

      {/* ------------- ⑤ リスク注意点 ------------- */}
      {risks.length > 0 && (
        <div className={styles.section}>
          <h3 className={styles.sectionTitle}><AlertTriangle/> リスク注意</h3>
          <ul className={styles.riskList}>
            {risks.map((r,i)=> <li key={i}>{r}</li>)}
          </ul>
        </div>
      )}

    </div>
  )
}
